contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test: deposit `value` into c, then call withdrawAll(); assert that
    // withdrawAll either reverts, or C's balance decreases by at most `value` and the recorded credit for this contract becomes zero.
    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value, "insufficient balance for test");
        // record C's external balance before deposit
        uint beforeC = address(c).balance;

        // perform deposit to create recorded credit for this contract in c
        c.deposit{value: value}(); if (__ESBMC_reverted()) return;

        // attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe C's external balance after withdrawAll
        uint afterC = address(c).balance;

        // Observe recorded credit for this contract by performing a harmless pattern:
        // We cannot read private variables, but we can infer that after a successful withdrawAll the contract's credit is zero
        // by attempting to deposit zero and then withdrawAll again: if recorded credit was nonzero after the first withdrawAll and the second withdrawAll would transfer additional funds,
        // that would change C's balance further. However performing actions that change state must be top-level and we're limited to a single public function.
        // Instead, we rely only on observable balances and a second read: if withdrawAll did NOT revert, then the recorded credit for this contract (which was value) must have been cleared by the contract logic when transfer succeeded.
        // We express the general rule conservatively: after a non-reverting withdrawAll, C's balance decreased by at most the deposited `value`.

        // General rule (single assert): If we deposited a positive `value`, then either withdrawAll reverted, or C's balance decreased by no more than `value` (i.e., beforeC >= afterC and beforeC - afterC <= value).
        // This avoids reading internal credit mapping and is a general safety: withdrawAll should not withdraw more than the contract's recorded credit for this caller.
        assert(value == 0 || reverted || (beforeC >= afterC && beforeC - afterC <= value));
    }

    receive() external payable { }
}

