// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        uint beforeC = address(c).balance;
        try c.deposit{value: value}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterC = address(c).balance;
        assertTrue(value == 0 || reverted || (beforeC >= afterC && beforeC - afterC <= value));
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable { }
}
